INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`,`to_ping`,`pinged`,`post_content_filtered`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>AFP — ширкати истеҳсолкунандаи лентаи обёрии қатрагӣ, қубури полиэтиленӣ ва қубури қатшавандаи риштадор дар шаҳри Наҷафобод (вилояти Исфаҳон, Эрон). Дар ин саҳифа мо мухтасар нишон медиҳем, ки чӣ истеҳсол мекунем ва чӣ гуна бо деҳқонон ва ташкилотҳои соҳаи кишоварзии Тоҷикистон ҳамкорӣ карда метавонем.</p>\n<h2>Хати истеҳсолот</h2>\n<ul>\n<li><strong>Лентаи обёрии қатрагӣ</strong> — барои зироатҳои қаторӣ: пахта, сабзавот, харбуза ва тарбуз. <a href="https://navar-abyari.ir/product/tg-tj-product-969/">Маҳсулотро бинед</a>.</li>\n<li><strong>Қубури полиэтиленӣ</strong> — барои хатҳои асосӣ ва тақсимкунандаи об дар киштзор.</li>\n<li><strong>Қубури қатшавандаи риштадор</strong> — барои интиқоли об аз канал ё насос ба киштзор. <a href="https://navar-abyari.ir/product/tg-tj-product-37848/">Маҳсулотро бинед</a>.</li>\n</ul>\n<p>Пеш аз ҳар фармоиш мо тавсия медиҳем, ки <a href="https://navar-abyari.ir/tg-tj-sanjishi-zamin/">замини кишоварзӣ санҷида шавад</a> ва <a href="https://navar-abyari.ir/tg-tj-sanjishhoi-sifat/">санҷишҳои сифати маҳсулот</a> дида шаванд.</p>\n<h2>Чаро об ва замин барои Тоҷикистон муҳим аст</h2>\n<p>Мувофиқи маълумоти ошкоро, танҳо тақрибан 28% хоки Тоҷикистон замини кишоварзӣ аст ва кишоварзии кишвар ба обёрӣ вобаста аст. Дар баъзе минтақаҳо, масалан дар Истаравшан ва ҳавзаи Қизилсув–Яхсу дар атрофи Кӯлоб, обёришавӣ талаботро пурра қонеъ намекунад. <small>(Сарчашма: <a href="https://en.wikipedia.org/wiki/Agriculture_in_Tajikistan" rel="nofollow noopener" target="_blank">Agriculture in Tajikistan (Wikipedia)</a>.)</small></p>\n<h2>Аз суханони расмии соли 2026</h2>\n<p>Дар паёми Наврӯзии соли 2026 ва суханронии 30 марти ҳамон сол масъалаи истифодаи оқилонаи об ва замин ҳамчун афзалият зикр шудааст:</p>\n<blockquote><p>«Бинобар ин, мо бояд аз тамоми захираву имкониятҳое, ки дар ихтиёр дорем, аз ҷумла аз ҳар як ваҷаб замин ва об самараноку оқилона истифода намоем.»</p><p><small>Сарчашма: <a href="https://president.tj/event/speeches/54919" rel="nofollow noopener" target="_blank">Presidential Nowruz greeting, 19 Mar 2026 (president.tj)</a>, 2026-03-19.</small></p></blockquote>\n<blockquote><p>«Таъкид менамоям, ки истифодаи оқилонаи об ва ҳар як ваҷаб замин шарти муҳимми таъмин намудани пешрафти иқтисоди миллӣ, амнияти озуқавории мамлакат ва зиндагии шоистаи мардуми кишвар мебошад.»</p><p><small>Сарчашма: <a href="https://president.tj/event/speeches/55133" rel="nofollow noopener" target="_blank">Presidential speech in Mastchoh, 30 Mar 2026 (president.tj)</a>, 2026-03-30.</small></p></blockquote>\n<p><em>Иқтибосҳо барои иттилоъ оварда шудаанд ва маънои тасдиқ ё дастгирии маҳсулоти AFP-ро аз ҷониби мақомоти давлатӣ надоранд.</em></p>\n<h2>Ҳамкорӣ бо AFP</h2>\n<p>Бо дарназардошти афзалияти рушди кишоварзӣ ва истифодаи самараноки об, мо омодаем бо хоҷагиҳои деҳқонӣ, корхонаҳои кишоварзӣ, шарикони тиҷоратӣ ва ташкилотҳои соҳа оид ба интихоби лента ва қубур машварат кунем. Нарх, шартҳои харид ва расонидани маҳсулот ба Тоҷикистон ҳангоми тамос алоҳида мувофиқа мешаванд. Маҳсулот кафолат дорад (<a href="https://navar-abyari.ir/tg-tj-kafolat/">шартҳои кафолат</a>); тафсилоти хизмати баъдифурӯшро дар <a href="https://navar-abyari.ir/tg-tj-hizmatrasoni/">ин саҳифа</a> бинед.</p>\n<p><strong>Тамос:</strong> <a href="tel:+989139310932">+98 913 931 0932</a> · <a href="https://navar-abyari.ir/tg-tj-tamos/">саҳифаи тамос</a> · <a href="https://navar-abyari.ir/tg-tj-shakli-darhost/">шакли дархост</a> · <a href="https://navar-abyari.ir/tj-rules/">қоидаҳои харид</a>.</p>','Хати истеҳсолот ва ҳамкорӣ бо соҳаи кишоварзии Тоҷикистон','','publish','closed','closed','tajikistan-istehsol-va-hamkori',NOW(),UTC_TIMESTAMP(),0,'https://navar-abyari.ir/tajikistan-istehsol-va-hamkori/',0,'page','',0,'','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `ha_posts` WHERE `post_name`='tajikistan-istehsol-va-hamkori' AND `post_type`='page');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @pid,'_rank_math_title','Хати истеҳсолот ва ҳамкорӣ бо кишоварзии Тоҷикистон | AFP' FROM DUAL WHERE @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE `post_id`=@pid AND `meta_key`='_rank_math_title');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @pid,'_rank_math_description','AFP — истеҳсолкунандаи лентаи обёрии қатрагӣ, қубури полиэтиленӣ ва қубури қатшавандаи риштадор. Шартҳои ҳамкорӣ бо деҳқонон ва ташкилотҳои Тоҷикистон.' FROM DUAL WHERE @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE `post_id`=@pid AND `meta_key`='_rank_math_description');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @pid,'rank_math_focus_keyword','лентаи обёрии қатрагӣ Тоҷикистон' FROM DUAL WHERE @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE `post_id`=@pid AND `meta_key`='rank_math_focus_keyword');
INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @pid,'_navar_tj_lang','tg-TJ' FROM DUAL WHERE @pid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE `post_id`=@pid AND `meta_key`='_navar_tj_lang');
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`,`to_ping`,`pinged`,`post_content_filtered`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>AFP — производитель капельной ленты, полиэтиленовых труб и армированных нитью плоскосворачиваемых рукавов (layflat) в городе Наджафабад (провинция Исфахан, Иран). На этой странице мы кратко рассказываем, что производим и как можем сотрудничать с фермерами и организациями аграрного сектора Таджикистана.</p>\n<h2>Что мы производим</h2>\n<ul>\n<li><strong>Капельная лента</strong> — для рядковых культур: хлопка, овощей, дынь и арбузов. <a href="https://navar-abyari.ir/product/tg-tj-product-969/">Смотреть продукцию</a>.</li>\n<li><strong>Полиэтиленовая труба</strong> — для магистральных и распределительных линий воды на поле.</li>\n<li><strong>Армированный нитью плоскосворачиваемый рукав (layflat)</strong> — для подачи воды из канала или от насоса на поле. <a href="https://navar-abyari.ir/product/tg-tj-product-37848/">Смотреть продукцию</a>.</li>\n</ul>\n<p>Перед каждым заказом рекомендуем <a href="https://navar-abyari.ir/tg-tj-sanjishi-zamin/">оценить землю</a> и ознакомиться с <a href="https://navar-abyari.ir/tg-tj-sanjishhoi-sifat/">проверками качества продукции</a>.</p>\n<h2>Почему вода и земля важны для Таджикистана</h2>\n<p>По открытым данным, лишь около 28% территории Таджикистана занимают сельскохозяйственные земли, а сельское хозяйство страны зависит от орошения. В некоторых районах, например в Истаравшане и в бассейне Кызылсу–Яхсу возле Куляба, орошение не полностью покрывает потребность в воде. <small>(Источник: <a href="https://en.wikipedia.org/wiki/Agriculture_in_Tajikistan" rel="nofollow noopener" target="_blank">Agriculture in Tajikistan (Wikipedia)</a>.)</small></p>\n<h2>Из официальных выступлений 2026 года</h2>\n<p>В новогоднем (Навруз) обращении 2026 года и в выступлении 30 марта того же года рациональное использование воды и земли названо приоритетом:</p>\n<blockquote><p>«Поэтому мы должны эффективно и рационально использовать все имеющиеся у нас ресурсы и возможности, в том числе каждую пядь земли и воду.»</p><p><small>Источник (оригинал на таджикском): <a href="https://president.tj/event/speeches/54919" rel="nofollow noopener" target="_blank">Поздравление Президента по случаю Навруза, 19.03.2026 (president.tj)</a>, 2026-03-19. Неофициальный перевод.</small></p></blockquote>\n<blockquote><p>«Подчёркиваю, что рациональное использование воды и каждой пяди земли является важным условием обеспечения развития национальной экономики, продовольственной безопасности страны и достойной жизни народа.»</p><p><small>Источник (оригинал на таджикском): <a href="https://president.tj/event/speeches/55133" rel="nofollow noopener" target="_blank">Выступление Президента в Мастчохе, 30.03.2026 (president.tj)</a>, 2026-03-30. Неофициальный перевод.</small></p></blockquote>\n<p><em>Цитаты приведены для информации и не означают одобрения или поддержки продукции AFP со стороны государственных органов.</em></p>\n<h2>Сотрудничество с AFP</h2>\n<p>Учитывая приоритет развития сельского хозяйства и эффективного использования воды, мы готовы консультировать фермерские хозяйства, сельскохозяйственные предприятия, торговых партнёров и отраслевые организации по выбору ленты и труб. Цена, условия покупки и доставки в Таджикистан согласовываются отдельно при обращении. На продукцию распространяется гарантия (<a href="https://navar-abyari.ir/tg-tj-kafolat/">условия гарантии</a>); подробности о послепродажном обслуживании — на <a href="https://navar-abyari.ir/tg-tj-hizmatrasoni/">этой странице</a>.</p>\n<p><strong>Контакты:</strong> <a href="tel:+989139310932">+98 913 931 0932</a> · <a href="https://navar-abyari.ir/tg-tj-tamos/">страница контактов</a> · <a href="https://navar-abyari.ir/tg-tj-shakli-darhost/">форма заявки</a> · <a href="https://navar-abyari.ir/tj-rules/">правила покупки</a>.</p>','Производство и сотрудничество с сельским хозяйством Таджикистана','','publish','closed','closed','tajikistan-proizvodstvo-i-sotrudnichestvo',NOW(),UTC_TIMESTAMP(),0,'https://navar-abyari.ir/tajikistan-proizvodstvo-i-sotrudnichestvo/',0,'page','',0,'','','' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `ha_posts` WHERE `post_name`='tajikistan-proizvodstvo-i-sotrudnichestvo' AND `post_type`='page');
